'use client'

import { useState } from 'react'

export interface QAItem {
  q: string
  a: string
}

interface QASectionProps {
  items: QAItem[]
}

/**
 * Accordion-style Q&A list.
 * Progressive disclosure (Agent-Skills principle): shows questions first,
 * expands answers on tap. Saves vertical space, keeps the page scannable.
 */
export default function QASection({ items }: QASectionProps) {
  const [expanded, setExpanded] = useState<number | null>(null)

  function toggle(idx: number) {
    setExpanded((prev) => (prev === idx ? null : idx))
  }

  return (
    <section>
      <h3 className="pixel-section-header">■ 100の質問 Q&amp;A</h3>

      <div>
        {items.map((item, idx) => {
          const isOpen = expanded === idx
          return (
            <div key={idx} style={{ borderBottom: '1px solid #c0c0d0' }}>
              {/* Question row */}
              <button
                onClick={() => toggle(idx)}
                className="w-full flex items-start gap-2 px-3 py-2 text-left cursor-pointer"
                style={{
                  background: idx % 2 === 0 ? '#f0efe8' : '#e8e8e0',
                  fontFamily: 'var(--font-pixel, monospace)',
                }}
                aria-expanded={isOpen}
              >
                <span
                  className="shrink-0 text-xs font-bold"
                  style={{ color: '#6060cc', minWidth: 28 }}
                >
                  Q{String(idx + 1).padStart(2, '0')}
                </span>
                <span className="flex-1 text-xs" style={{ color: '#1a1a4e', lineHeight: '1.8' }}>
                  {item.q}
                </span>
                <span className="text-xs shrink-0" style={{ color: '#6060cc' }}>
                  {isOpen ? '▲' : '▼'}
                </span>
              </button>

              {/* Answer (expanded) */}
              {isOpen && (
                <div
                  className="px-3 py-2 flex gap-2"
                  style={{
                    background: '#e8e8f8',
                    borderLeft: '4px solid #6060cc',
                    fontFamily: 'var(--font-pixel, monospace)',
                  }}
                >
                  <span className="shrink-0 text-xs font-bold" style={{ color: '#cc2020' }}>
                    A:
                  </span>
                  <span className="text-xs" style={{ color: '#1a1a4e', lineHeight: '1.8' }}>
                    {item.a}
                  </span>
                </div>
              )}
            </div>
          )
        })}
      </div>
    </section>
  )
}
